// Sequential MCP stdio client: sends one request, waits for its response,
// then sends the next. The earlier burst-write test fired all ten requests in
// one chunk and the server's async handlers interleaved them, so recall could
// answer before inscribe's writeFile resolved. Claude Code is sequential; this
// mirrors that.
import { spawn } from "node:child_process";
import { readFile } from "node:fs/promises";

const [serverPath, cwd] = process.argv.slice(2);
const child = spawn(process.execPath, [serverPath], {
  cwd,
  stdio: ["pipe", "pipe", "inherit"],
});

let buffer = "";
const waiters = new Map();
child.stdout.on("data", (chunk) => {
  buffer += chunk;
  let nl;
  while ((nl = buffer.indexOf("\n")) !== -1) {
    const line = buffer.slice(0, nl).trim();
    buffer = buffer.slice(nl + 1);
    if (!line) continue;
    const msg = JSON.parse(line);
    const waiter = waiters.get(msg.id);
    if (waiter) {
      waiters.delete(msg.id);
      waiter(msg);
    }
  }
});

let nextId = 1;
function request(method, params) {
  const id = nextId++;
  return new Promise((resolve) => {
    waiters.set(id, resolve);
    child.stdin.write(JSON.stringify({ jsonrpc: "2.0", id, method, params }) + "\n");
  });
}
function notify(method, params) {
  child.stdin.write(JSON.stringify({ jsonrpc: "2.0", method, params }) + "\n");
}

const text = (r) => r.result?.content?.[0]?.text ?? JSON.stringify(r);
const call = async (name, args = {}) => text(await request("tools/call", { name, arguments: args }));

const init = await request("initialize", {
  protocolVersion: "2024-11-05",
  capabilities: {},
  clientInfo: { name: "sparse-verify", version: "0" },
});
notify("notifications/initialized");
console.log("  serverInfo:            ", JSON.stringify(init.result.serverInfo));

const tools = await request("tools/list");
console.log("  tools:                 ", JSON.stringify(tools.result.tools.map((t) => t.name)));

const savePath = `${cwd}/.claude/dungeon.local.md`;
const state = "---\nscript: unix-catacombs\nscene: entrance\nhealth: 75\n---\n\n# Adventure Log\n";

console.log("  recall (no save):      ", JSON.stringify(await call("recall")));
console.log("  inscribe:              ", JSON.stringify(await call("inscribe", { content: state })));
console.log("  bytes on disk:         ", (await readFile(savePath, "utf-8")).length);
